let out = $('Video Copy Agent').first().json.output;
if (typeof out === 'string') { out = JSON.parse(out); }
const frames = Array.isArray(out.frames) ? out.frames : [];

// Defensive validation: the agent sometimes omits a template's required
// token(s) (real incident: body-standout-line without LINE_1), which the
// render service correctly rejects with a 400 -- but that used to kill the
// whole run. Instead, drop only the bad frame(s) and keep going; log what
// was dropped so it's visible in the execution, not silent.
const REQUIRED = {
  'body-stroke-hook': ['HEADLINE_TOP', 'HEADLINE_PAYOFF'],
  'body-word-emphasis': ['HEADLINE'],
  'body-split-contrast': ['CLAUSE_A', 'CLAUSE_B'],
  'body-bridge': ['HEADLINE'],
  'body-standout-line': ['LINE_1'],
  'close-cta': ['HEADLINE', 'CTA_TEXT']
};
const REPEAT_KEY = {
  'body-sequential-list': 'LINE_TEXT',
  'body-step-list': 'STEP_LABEL'
};

const dropped = [];
const valid = frames.filter((f) => {
  if (!f || !f.template) { dropped.push({ frame: f, reason: 'missing template' }); return false; }
  const tokens = f.tokens || {};
  if (REQUIRED[f.template]) {
    const missing = REQUIRED[f.template].filter((k) => !tokens[k]);
    if (missing.length) {
      dropped.push({ id: f.id, template: f.template, reason: `missing tokens: ${missing.join(', ')}` });
      return false;
    }
  }
  if (REPEAT_KEY[f.template]) {
    const items = Array.isArray(f.items) ? f.items : [];
    const key = REPEAT_KEY[f.template];
    const bad = items.length === 0 || items.some((it) => !it || !it[key]);
    if (bad) {
      dropped.push({ id: f.id, template: f.template, reason: `missing/empty items[].${key}` });
      return false;
    }
  }
  return true;
});

if (dropped.length) {
  console.log('Dropped invalid frame(s):', JSON.stringify(dropped));
}

const hasClosing = valid.length > 0 && valid[valid.length - 1].template === 'close-cta';
if (valid.length < 2 || !hasClosing) {
  throw new Error(
    `Video plan invalid after dropping bad frames -- ${valid.length} usable frame(s), ` +
    `closing frame present: ${hasClosing}. Dropped: ${JSON.stringify(dropped)}`
  );
}

const theme = {
  bg: $('Video Brief').item.json.theme_bg,
  text: $('Video Brief').item.json.theme_text,
  lead_text: $('Video Brief').item.json.theme_lead_text,
  accent: $('Video Brief').item.json.theme_accent,
  accent_text: $('Video Brief').item.json.theme_accent_text,
  font_family: $('Video Brief').item.json.theme_font,
  logo_url: $('Video Brief').item.json.theme_logo_url,
  bg_pattern: $('Video Brief').item.json.theme_bg_pattern
};

// bed_audio_path is a path INSIDE the Modal container (mounted from this
// repo's builder/audio/ dir by service/app.py's build_image) -- not a local
// path on this machine. Leave it empty to render silent.
const bedPath = $('Video Brief').item.json.bed_audio_path;
const audio = bedPath ? {
  bed_path: bedPath,
  bed_volume: $('Video Brief').item.json.bed_audio_volume
} : undefined;

return [{
  json: {
    projectId: out.projectId || 'video',
    youtubeTitle: out.youtubeTitle || '',
    youtubeDescription: out.youtubeDescription || '',
    droppedFrames: dropped,
    plan: {
      project_id: out.projectId || 'video',
      frames: valid,
      audio: audio
    },
    theme: theme
  }
}];
